using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class PublicWorksTests
{
 static readonly EntityId Site=new("site:castle");
 internal static WorldSession Start()=>HouseholdCourtTests.Start();
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 static WorksInput Input(WorldSession s,WorksKind kind=WorksKind.Agriculture)=>new(new("request:works/"+s.Revision),Site,kind);
 [Fact]public void ConstructionConsumesActualHouseRiceWoodAndMoneyAndHoldsLaborUntilCompletion(){var s=Start();var w=s.DiagnosticSnapshot();long money=s.HouseTreasuryView()!.HouseCash,wood=w.Materials!.Houses.Single(h=>h.Site==Site).Wood,rice=s.CommunityEconomyView()!.Accounts.HouseRice;var i=Input(s);Good(s.StartPublicWork(i,s.Revision));w=s.DiagnosticSnapshot();Assert.Equal(rice-100,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(money-50,s.HouseTreasuryView()!.HouseCash);Assert.Equal(wood-5,w.Materials!.Houses.Single(h=>h.Site==Site).Wood);Assert.Equal(80,s.CommunityEconomyView()!.Accounts.Workforce);Assert.Equal(0,PublicWorks.Level(w,Site,WorksKind.Agriculture));Assert.Equal(ResultCode.AlreadyAccepted,s.StartPublicWork(i,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.StartPublicWork(Input(s,WorksKind.Commerce),s.Revision).Code);NewGameWorldTests.At(s,7*86400);Assert.Equal(1,PublicWorks.Level(s.DiagnosticSnapshot(),Site,WorksKind.Agriculture));Assert.Equal(100,s.CommunityEconomyView()!.Accounts.Workforce);ContractValidation.Validate(s.DiagnosticSnapshot());}
 [Theory][InlineData(WorksKind.Mine)][InlineData(WorksKind.Pasture)][InlineData(WorksKind.Port)][InlineData(WorksKind.TradeShip)][InlineData(WorksKind.Warship)]public void UnsupportedLandAndPortCannotFabricateFacilities(WorksKind kind){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.StartPublicWork(Input(s,kind),s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
 [Fact]public void NonAdministratorCannotOrderPublicWork(){var s=HouseholdCourtTests.Start(HouseholdCourtTests.Ronin.Value);Assert.Equal(ResultCode.NotAvailable,s.StartPublicWork(Input(s),s.Revision).Code);}
 [Fact]public void RealSaveMidConstructionHasSameCompletionAndAccounts(){var s=Start();Good(s.StartPublicWork(Input(s,WorksKind.Workshop),s.Revision));NewGameWorldTests.At(s,3*86400);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"works-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"mid",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("mid"),host.Current,host.Current.Revision));foreach(var x in new[]{s,host.Current})NewGameWorldTests.At(x,8*86400);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
 [Fact]public void HistoricalLandCapacityIsExplicitlyTrialAndDiffersByLand(){var s=Start();var w=s.DiagnosticSnapshot();Assert.True(PublicWorks.Capacity(w,Site,WorksKind.Agriculture)>PublicWorks.Capacity(w,new("site:kofu"),WorksKind.Agriculture));Assert.Equal(0,PublicWorks.Capacity(w,Site,WorksKind.Mine));Assert.True(PublicWorks.Capacity(w,new("site:kofu"),WorksKind.Mine)>0);Assert.Equal(2,PublicWorks.Capacity(w,Site,WorksKind.Commerce,100));}
 [Fact]public void LegacyBytesRemainExactAndEmptyModuleCannotBeInjected(){var w=Start().DiagnosticSnapshot();var b=ContractJson.Write(w);Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));w.PublicWorks=new(1,PublicWorks.Policy,[],[]);Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void ForgedWorkCannotShortenTheTermOrCreateResources(){var s=Start();Good(s.StartPublicWork(Input(s),s.Revision));var w=s.DiagnosticSnapshot();var q=w.PublicWorks!.Orders[0];w.PublicWorks=w.PublicWorks with{Orders=[q with{Due=1}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}

 internal static WorldSession PortStart(){var setup=NewGameWorldTests.Setup([NewGameWorldTests.Officer("created:port-lord",StartTemplate.Daimyo,"site:sakai")],[new("created:port-lord","created:port-house",["site:sakai"],false)]);return new(NewGameWorld.Create(setup.World,setup.Registered,"created:port-lord",42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseSuccession.Policy));}
 [Fact]public void RealPortConstructionBuildsOwnedShipAndMaintenanceSpendsRiceAndCoins(){var s=PortStart();var port=new EntityId("site:sakai");Good(s.StartPublicWork(new(new("request:port-work"),port,WorksKind.Port),s.Revision));NewGameWorldTests.At(s,7*86400);Good(s.StartPublicWork(new(new("request:ship-build"),port,WorksKind.TradeShip),s.Revision));Assert.Empty(PublicWorks.Ships(s.DiagnosticSnapshot()));NewGameWorldTests.At(s,21*86400);var ship=Assert.Single(PublicWorks.Ships(s.DiagnosticSnapshot()));Assert.Equal(new EntityId("created:port-house"),ship.Owner);Assert.False(ship.Maintained);long cash=s.HouseTreasuryView()!.HouseCash,rice=s.CommunityEconomyView()!.Accounts.HouseRice;Good(s.MaintainPublicShip(new("request:ship-care"),ship.Id,s.Revision));Assert.Equal(cash-2,s.HouseTreasuryView()!.HouseCash);Assert.Equal(rice-1,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.True(PublicWorks.Ships(s.DiagnosticSnapshot()).Single().Maintained);Assert.Equal(ResultCode.NotAvailable,s.MaintainPublicShip(new("request:ship-care-again"),ship.Id,s.Revision).Code);}
 [Fact]public void CompletedWorkshopChangesActualProductionWithoutInventingRawStock(){var a=Start();var b=Start();Good(a.StartPublicWork(Input(a,WorksKind.Workshop),a.Revision));NewGameWorldTests.At(a,32*86400);NewGameWorldTests.At(b,32*86400);long madeA=a.DiagnosticSnapshot().Materials!.Months.Where(m=>m.Site==Site).Sum(m=>m.WeaponsMade),madeB=b.DiagnosticSnapshot().Materials!.Months.Where(m=>m.Site==Site).Sum(m=>m.WeaponsMade);Assert.True(madeA>madeB);ContractValidation.Validate(a.DiagnosticSnapshot());}
 [Fact]public void CompletedAgricultureAffectsTheActualAutumnHarvest(){var a=Start();var b=Start();Good(a.StartPublicWork(Input(a),a.Revision));long autumn=(new DateOnly(1560,10,1).DayNumber-new DateOnly(1560,1,1).DayNumber)*86400L;NewGameWorldTests.At(a,autumn);NewGameWorldTests.At(b,autumn);Assert.True(a.CommunityEconomyView()!.Accounts.Harvested>b.CommunityEconomyView()!.Accounts.Harvested);}
 [Fact]public void NpcHeadContinuesRealConstructionWithinItsOwnResources(){var s=HouseholdCourtTests.Start(HouseholdCourtTests.Ronin.Value);var method=typeof(WorldSession).GetMethod("Change",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!;method.Invoke(s,[new Action<ContractWorld>(w=>PublicWorks.Execute(w,new(new("request:npc-first-work"),Site,WorksKind.Agriculture),new("person:nobunaga"))),null]);NewGameWorldTests.At(s,8*86400);Assert.True(s.DiagnosticSnapshot().PublicWorks!.Orders.Length>=2);Assert.All(s.DiagnosticSnapshot().PublicWorks!.Orders,q=>Assert.Equal(new EntityId("person:nobunaga"),q.Actor));}
}
